const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); // You must include this line

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2018-07-01';
    const end = '2018-09-01'; // exclusive end -> covers July+August
    const gaul1 = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const gaul0 = ee.FeatureCollection('FAO/GAUL/2015/level0');

    const keralaFC = gaul1.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'India'),
      ee.Filter.eq('ADM1_NAME', 'Kerala')
    ));
    const sriFC = gaul0.filter(ee.Filter.eq('ADM0_NAME', 'Sri Lanka'));

    const keralaCount = await keralaFC.size().getInfo();
    const sriCount = await sriFC.size().getInfo();
    if (!keralaCount || !sriCount) {
      console.log('Boundary fetch: Kerala features=' + keralaCount + ', SriLanka features=' + sriCount);
      console.log('C1');
      return;
    }
    const kerala = keralaFC.geometry();
    const sri = sriFC.geometry();

    // 2. Data Acquisition & Check
    let dataset = 'UCSB-CHG/CHIRPS/DAILY';
    let col = ee.ImageCollection(dataset).filterDate(start, end).select('precipitation');
    let imgCount = await col.size().getInfo();
    if (imgCount === 0) {
      // Fallback to ERA5-Land Daily Aggregated total precipitation (m). Convert to mm.
      dataset = 'ECMWF/ERA5_LAND/DAILY_AGGR';
      col = ee.ImageCollection(dataset).filterDate(start, end).select('total_precipitation_sum').map(img => img.multiply(1000).rename('precipitation'));
      imgCount = await col.size().getInfo();
      if (imgCount === 0) {
        console.log('Images: 0');
        console.log('C1');
        return;
      }
    }

    // 3. Processing
    const sumImg = col.sum().rename('precipitation'); // total mm over period
    const reducer = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const kerStats = await sumImg.reduceRegion({
      reducer: reducer,
      geometry: kerala,
      scale: 5000,
      maxPixels: 1e9,
      bestEffort: true
    }).getInfo();
    const sriStats = await sumImg.reduceRegion({
      reducer: reducer,
      geometry: sri,
      scale: 5000,
      maxPixels: 1e9,
      bestEffort: true
    }).getInfo();

    const kMean = kerStats ? kerStats.precipitation_mean : null;
    const kCount = kerStats ? kerStats.precipitation_count : 0;
    const sMean = sriStats ? sriStats.precipitation_mean : null;
    const sCount = sriStats ? sriStats.precipitation_count : 0;

    // 4. Validation
    console.log(`Dataset: ${dataset}, Images: ${imgCount}`);
    if (!kCount || !sCount) {
      console.log(`Kerala pixels: ${kCount}, SriLanka pixels: ${sCount}`);
      console.log('C2');
      return;
    }
    const invalid = (v) => (v === null || !isFinite(v) || v < 0 || v > 5000);
    if (invalid(kMean) || invalid(sMean)) {
      console.log(`Kerala mean(mm): ${kMean}, SriLanka mean(mm): ${sMean}`);
      console.log('C3');
      return;
    }

    // 5. Output stats and Final Answer
    console.log(`Kerala pixels: ${kCount}, mean_mm: ${kMean.toFixed(1)}`);
    console.log(`SriLanka pixels: ${sCount}, mean_mm: ${sMean.toFixed(1)}`);
    console.log(`Difference (Kerala - SriLanka) mm: ${(kMean - sMean).toFixed(1)}`);

    if (kMean > sMean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
